// Fetch confirmed warehouse tasks from SAP S/4HANA EWM
// Uses the WAREHOUSEORDER_0001 OData API
// GET https://your-s4hana.company.com/sap/opu/odata/sap/WAREHOUSEORDER_0001/WarehouseTask?$filter=WarehouseTaskStatus eq 'C'
const S4_BASE_URL = 'https://your-s4hana.company.com/sap/opu/odata/sap/WAREHOUSEORDER_0001';
const CAP_BASE_URL = 'https://your-cap-service.company.com';
return [{ json: { triggerTime: new Date().toISOString(), s4BaseUrl: S4_BASE_URL, capBaseUrl: CAP_BASE_URL } }];

// Fetch all ACTIVE TOR timer records from CAP service
// GET https://your-cap-service.company.com/TOREvents?$filter=status eq 'ACTIVE'
// Response shape: [{ batchId, materialId, fridgeOutTimestamp, torLimitMinutes, warningAlertSentAt, breachAlertSentAt, status }]
const items = $input.all().map(item => ({ json: { ...item.json, activeTimers: [] } }));
return items;

// Evaluate elapsed TOR time for each active batch against warning and breach thresholds
const TOR_WARNING_PERCENT = 0.8;
const TOR_BREACH_PERCENT = 1.0;

const now = new Date();
const results = [];
const timers = $input.first().json.activeTimers || [];

for (const timer of timers) {
  const fridgeOut = new Date(timer.fridgeOutTimestamp);
  const elapsedMinutes = (now - fridgeOut) / 60000;
  const torLimitMinutes = timer.torLimitMinutes;
  const remainingMinutes = torLimitMinutes - elapsedMinutes;
  const elapsedPercent = elapsedMinutes / torLimitMinutes;

  let alertLevel = 'NONE';
  if (elapsedPercent >= TOR_BREACH_PERCENT && !timer.breachAlertSentAt) {
    alertLevel = 'BREACH';
  } else if (elapsedPercent >= TOR_WARNING_PERCENT && !timer.warningAlertSentAt) {
    alertLevel = 'WARNING';
  } else if (timer.status === 'COMPLETED_FRIDGE_IN') {
    alertLevel = 'PUTAWAY';
  }

  results.push({
    json: {
      ...timer,
      elapsedMinutes: Math.round(elapsedMinutes * 10) / 10,
      remainingMinutes: Math.round(remainingMinutes * 10) / 10,
      elapsedPercent: Math.round(elapsedPercent * 1000) / 1000,
      alertLevel
    }
  });
}

if (results.length === 0) {
  return [{ json: { alertLevel: 'NONE', message: 'No active TOR timers requiring action' } }];
}

return results;

// NOTIFICATION ROUTING CONFIGURATION
// Warning alerts go to Warehouse Manager + Shopfloor Manager ONLY
const NOTIFICATION_CONFIG = {
  WAREHOUSE_MANAGER_EMAIL: 'warehouse.manager@company.com',
  SHOPFLOOR_MANAGER_EMAIL: 'shopfloor.manager@company.com',
  NOTIFICATION_SUBJECT_PREFIX: '[TOR WARNING]'
};

const batchData = $input.first().json;
const agentRecommendation = batchData.response || 'Advisory unavailable';

const logEntry = `M2.achieved: warning alert issued for batch ${batchData.batchId}, elapsed ${batchData.elapsedMinutes} min of ${batchData.torLimitMinutes} min, AI recommendation: ${agentRecommendation}`;
console.log(logEntry);

return [{
  json: {
    ...batchData,
    notification: {
      recipients: [NOTIFICATION_CONFIG.WAREHOUSE_MANAGER_EMAIL, NOTIFICATION_CONFIG.SHOPFLOOR_MANAGER_EMAIL],
      subject: `${NOTIFICATION_CONFIG.NOTIFICATION_SUBJECT_PREFIX} Batch ${batchData.batchId} approaching TOR limit`,
      body: `TOR WARNING ALERT\nBatch: ${batchData.batchId}\nMaterial: ${batchData.materialId}\nElapsed: ${batchData.elapsedMinutes} min of ${batchData.torLimitMinutes} min (${(batchData.elapsedPercent*100).toFixed(0)}%)\nRemaining: ${batchData.remainingMinutes} min\n\nAdvisory: ${agentRecommendation}`
    },
    agentRecommendation
  }
}];

// Agent timed out or returned empty — send warning without AI recommendation
const NOTIFICATION_CONFIG = {
  WAREHOUSE_MANAGER_EMAIL: 'warehouse.manager@company.com',
  SHOPFLOOR_MANAGER_EMAIL: 'shopfloor.manager@company.com'
};

const item = $input.first().json;
console.log(`M2.missed: advisory agent failed for batch ${item.batchId} — sending warning without recommendation`);

return [{
  json: {
    ...item,
    notification: {
      recipients: [NOTIFICATION_CONFIG.WAREHOUSE_MANAGER_EMAIL, NOTIFICATION_CONFIG.SHOPFLOOR_MANAGER_EMAIL],
      subject: `[TOR WARNING] Batch ${item.batchId} — Advisory Unavailable`,
      body: `TOR WARNING: Batch ${item.batchId} at ${(item.elapsedPercent*100).toFixed(0)}% of TOR limit. Remaining: ${item.remainingMinutes} min. Advisory agent unavailable — please assess manually.`
    },
    agentRecommendation: 'Unavailable'
  }
}];

// Update TOR event record in CAP service after warning
// PATCH https://your-cap-service.company.com/TOREvents/{id}
// Set: warningAlertSentAt, aiRecommendation, status remains 'ACTIVE'
const item = $input.first().json;
console.log(`CAP warning record updated for batch ${item.batchId}`);
return [{ json: { ...item, warningRecordUpdated: true, warningAlertSentAt: new Date().toISOString() } }];

// Look up physical stock record from SAP S/4HANA EWM
// GET https://your-s4hana.company.com/sap/opu/odata/sap/CE_WHSEPHYSICALSTOCKPRODUCTS_0001/WarehousePhysicalStockProducts?$filter=Batch eq '{batchId}'
const item = $input.first().json;
return [{ json: { ...item, stockRecordFetched: true } }];

// Change stock type to BLOCKED via ChangeStockType OData action
// POST https://your-s4hana.company.com/sap/opu/odata/sap/CE_WHSEPHYSICALSTOCKPRODUCTS_0001/WarehousePhysicalStockProducts({key})/ChangeStockType
// Body: { EWMStockType: 'S2', EWMGoodsMovementEntryUnit: 'EA', EWMGoodsMovementEntryQuantity: 1 }
// S2 = EWM blocked stock type (unrestricted-use → blocked)
const item = $input.first().json;
console.log(`M3.achieved: TOR breach confirmed for batch ${item.batchId}, stock blocked in S/4HANA, breach notifications sent to all roles`);
return [{ json: { ...item, stockBlocked: true, stockBlockedAt: new Date().toISOString() } }];

// NOTIFICATION ROUTING CONFIGURATION
// Breach alerts go to ALL THREE roles
const NOTIFICATION_CONFIG = {
  WAREHOUSE_MANAGER_EMAIL: 'warehouse.manager@company.com',
  SHOPFLOOR_MANAGER_EMAIL: 'shopfloor.manager@company.com',
  QUALITY_MANAGER_EMAIL: 'quality.manager@company.com',
  NOTIFICATION_SUBJECT_PREFIX: '[TOR BREACH]'
};

const item = $input.first().json;
const stockStatus = item.stockBlocked ? 'BLOCKED in S/4HANA' : 'BLOCK FAILED — manual intervention required';

const logEntry = item.stockBlocked
  ? `M3.achieved: TOR breach confirmed for batch ${item.batchId}, stock blocked in S/4HANA, breach notifications sent to all roles`
  : `M3.missed: TOR breach detected for batch ${item.batchId} but stock block action failed; manual intervention required`;
console.log(logEntry);

return [{
  json: {
    ...item,
    breachNotification: {
      recipients: [
        NOTIFICATION_CONFIG.WAREHOUSE_MANAGER_EMAIL,
        NOTIFICATION_CONFIG.SHOPFLOOR_MANAGER_EMAIL,
        NOTIFICATION_CONFIG.QUALITY_MANAGER_EMAIL
      ],
      subject: `${NOTIFICATION_CONFIG.NOTIFICATION_SUBJECT_PREFIX} Batch ${item.batchId} TOR EXCEEDED`,
      body: `TOR BREACH — IMMEDIATE ACTION REQUIRED\nBatch: ${item.batchId}\nMaterial: ${item.materialId}\nElapsed: ${item.elapsedMinutes} min (limit: ${item.torLimitMinutes} min)\nStock Status: ${stockStatus}\n\nWarehouse Manager: Transfer to scrap bin immediately.\nShopfloor Manager: Do NOT use this batch in production.\nQuality Manager: Initiate deviation report per site SOP.`
    }
  }
}];

// Update TOR event record in CAP service after breach
// PATCH https://your-cap-service.company.com/TOREvents/{id}
// Set: breachAlertSentAt, stockBlockedAt, status = 'BREACHED'
const item = $input.first().json;
return [{ json: { ...item, breachRecordUpdated: true, status: 'BREACHED', breachAlertSentAt: new Date().toISOString() } }];

// TOR timer stopped — batch confirmed put-away in destination fridge on PSA
// Write complete, immutable audit record to CAP service (GxP compliance)
// PATCH https://your-cap-service.company.com/TOREvents/{id}
// Set: fridgeInTimestamp, totalExposureMinutes, status = 'COMPLETED'
const item = $input.first().json;
const now = new Date();
const fridgeOut = new Date(item.fridgeOutTimestamp || now);
const totalMinutes = Math.round((now - fridgeOut) / 60000 * 10) / 10;

console.log(`M4.achieved: TOR timer stopped for batch ${item.batchId}, total exposure ${totalMinutes} min, full audit record written`);

return [{
  json: {
    batchId: item.batchId,
    materialId: item.materialId,
    fridgeOutTimestamp: item.fridgeOutTimestamp,
    fridgeInTimestamp: now.toISOString(),
    totalExposureMinutes: totalMinutes,
    torLimitMinutes: item.torLimitMinutes,
    warningAlertSentAt: item.warningAlertSentAt || null,
    breachAlertSentAt: item.breachAlertSentAt || null,
    status: 'COMPLETED',
    actionTaken: item.stockBlocked
      ? 'STOCK_BLOCKED'
      : (item.breachAlertSentAt ? 'BREACH_NOTIFIED' : 'WITHIN_LIMIT')
  }
}];
